import type { Account } from "./accounts";
import { db } from "./db";

async function loadAccount(userId: string): Promise<Account> {
  return db.one<Account>("SELECT * FROM users WHERE id = $1", [userId]);
}

export async function updateName(userId: string, name: string): Promise<void> {
  const account = await loadAccount(userId);
  if (account.status === "suspended") {
    throw new Error("Account is not active");
  }
  await db.query("UPDATE users SET name = $1 WHERE id = $2", [name, userId]);
}

export async function updatePhone(userId: string, phone: string): Promise<void> {
  const account = await loadAccount(userId);
  if (account.status === "suspended") {
    throw new Error("Account is not active");
  }
  await db.query("UPDATE users SET phone = $1 WHERE id = $2", [phone, userId]);
}

export async function setAvatar(userId: string, avatarUrl: string): Promise<void> {
  const account = await loadAccount(userId);
  if (account.status === "suspended") {
    throw new Error("Account is not active");
  }
  await db.query("UPDATE users SET avatar_url = $1 WHERE id = $2", [avatarUrl, userId]);
}

export async function getProfile(userId: string): Promise<Account> {
  const account = await loadAccount(userId);
  if (account.status === "suspended") {
    throw new Error("Account is not active");
  }
  return account;
}

